WITH flattened_attrs AS (SELECT id, customer_id, created_at, items, ship_to, AGGREGATE(items, CAST(0 AS DOUBLE), (acc, item) -> acc + item.qty * item.price, acc -> ROUND(acc, 2)) AS basket_amount, ship_to.zip AS ship_zip, COALESCE(ship_to.city, 'UNKNOWN') AS city_or_unknown, attributes['device'] AS device, attributes['utm_source'] AS utm_source FROM carts WHERE TO_DATE(created_at) >= '2023-04-18') SELECT customer_id, DATE_TRUNC('HOUR', created_at) AS hour_window, CASE WHEN basket_amount >= 1300 THEN 'PREMIUM' ELSE 'STANDARD' END AS basket_amount_tier, SUM(basket_amount) AS total_basket_amount, MAX(created_at) AS last_created_at, MIN(created_at) AS first_seen, ROUND(AVG(basket_amount), 2) AS avg_basket_amount, SUM(basket_amount) AS total_basket_amount_2 FROM flattened_attrs GROUP BY customer_id, DATE_TRUNC('HOUR', created_at), CASE WHEN basket_amount >= 1300 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING ROUND(AVG(basket_amount), 2) > 0 ORDER BY total_basket_amount_2 DESC;
